import { routing } from '@/i18n/routing'

export const BASE_URL = 'https://www.samuel-lecomte.fr'

/**
 * Build hreflang alternates for a given path.
 * Used by layouts (generateMetadata) and sitemap.
 */
export function buildAlternates(path: string) {
  return {
    languages: Object.fromEntries([
      ...routing.locales.map((loc) => [loc, `${BASE_URL}/${loc}${path}`]),
      ['x-default', `${BASE_URL}/${routing.defaultLocale}${path}`],
    ]),
  }
}

/**
 * The site-wide share image generated by app/opengraph-image.tsx. Layouts that
 * redefine `openGraph` replace the inherited object, image included, so they
 * list it again (V6-COD-33).
 */
export const OG_IMAGE = {
  url: '/opengraph-image',
  width: 1200,
  height: 630,
  alt: 'Samuel Lecomte - Graduate in Physics and Data Science',
  type: 'image/png',
}
